"use client";
import { useEffect, useRef, useState, type ComponentProps } from "react";
import { cn } from "./cn";
import { useIndicator } from "./use-indicator";
import { useSwipeSelect } from "./use-swipe-select";
import { haptic } from "./haptics";

export interface TabsProps<T extends string> extends Omit<ComponentProps<"div">, "onChange" | "children" | "role" | "aria-label"> {
  value: T;
  /** `badge` shows a small dot: something in that tab needs a look. */
  tabs: { id: T; label: string; badge?: boolean }[];
  onChange: (id: T) => void;
  /** Names the tab list for screen readers. */
  label: string;
}

/** Pill tab bar. A dark thumb slides to the chosen tab, and the bar scrolls sideways when it does not fit. */
export function Tabs<T extends string>({ value, tabs, onChange, label, className, style, ...rest }: TabsProps<T>) {
  const root = useRef<HTMLDivElement>(null);
  // Swiping across the tabs only makes sense when they all fit. When they do not, a sideways swipe scrolls the list instead.
  const [roomy, setRoomy] = useState(true);
  useEffect(() => {
    const el = root.current; if (!el) return;
    const ro = new ResizeObserver(() => setRoomy(el.scrollWidth <= el.clientWidth + 1));
    ro.observe(el);
    return () => ro.disconnect();
  }, [tabs.length]);
  const { box, ready } = useIndicator(root, "[aria-selected=true]", `${value}|${tabs.length}`);
  const choose = (id: T) => { if (id !== value) haptic("select"); onChange(id); };
  const swipe = useSwipeSelect({ index: Math.max(0, tabs.findIndex((t) => t.id === value)), onIndex: (i) => choose(tabs[i].id), itemSelector: ".tab" });
  return (
    <div ref={root} data-slot="tabs" className={cn("tabs", className)} role="tablist" aria-label={label} style={{ ...style, ...(roomy ? { touchAction: "pan-y" } : {}) }} {...rest} {...(roomy ? swipe : {})}>
      {box ? <span className={cn("tab-ind", ready && "ready")} aria-hidden="true" style={{ width: box.w, transform: `translateX(${box.x}px)` }} /> : null}
      {tabs.map((t) => (
        <button key={t.id} type="button" className="tab" role="tab" aria-selected={value === t.id} onClick={() => choose(t.id)}>
          {t.label}{t.badge ? <span className="dotb" title="Needs a look" /> : null}
        </button>
      ))}
    </div>
  );
}

/* Tabs. */
.tabs{position:relative;display:flex;gap:6px;overflow-x:auto;margin-bottom:14px;padding-bottom:4px}
.tab{position:relative;z-index:1;display:inline-flex;align-items:center;gap:8px;padding:9px 15px;border-radius:99px;font-weight:600;color:var(--ink2);white-space:nowrap;background:transparent}
.tab[aria-selected=true]{color:var(--tile)}
.tab-ind{position:absolute;top:0;bottom:4px;left:0;border-radius:99px;background:var(--ink);z-index:0;pointer-events:none}
.tab-ind.ready{transition:transform .5s var(--spring),width .3s var(--ease-out)}
@media (prefers-reduced-motion:reduce){.tab-ind.ready{transition:none}}
.tab .dotb{width:8px;height:8px;border-radius:50%;background:var(--clay)}
.table{width:100%;border-collapse:collapse;font-size:0.8438rem}
.table th{font:500 0.6562rem var(--f-mono);letter-spacing:.08em;text-transform:uppercase;color:var(--ink3);text-align:left;padding:6px 10px 8px 0}
.table td{padding:10px 10px 10px 0;border-top:1px solid var(--line);vertical-align:middle}
@media (max-width:700px){
  .tabs{margin-bottom:10px}
}

"use client";
import { useLayoutEffect, useState, type RefObject } from "react";

/**
 * Measures the element matching `selector` inside `root` so a single thumb can slide under the active item.
 * Re-measures when `dep` changes and whenever the root or its children resize. `ready` turns true one frame
 * after the first measurement, so the thumb appears in place instead of sliding in from the left.
 */
export function useIndicator(root: RefObject<HTMLElement | null>, selector: string, dep: unknown, childSelector = "button") {
  const [box, setBox] = useState<{ x: number; w: number } | null>(null);
  const [ready, setReady] = useState(false);
  useLayoutEffect(() => {
    const el = root.current;
    if (!el) return;
    const measure = () => {
      const on = el.querySelector<HTMLElement>(selector);
      if (on) setBox((b) => (b && b.x === on.offsetLeft && b.w === on.offsetWidth ? b : { x: on.offsetLeft, w: on.offsetWidth }));
    };
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    el.querySelectorAll(childSelector).forEach((c) => ro.observe(c));
    const raf = requestAnimationFrame(() => setReady(true));
    return () => { ro.disconnect(); cancelAnimationFrame(raf); };
  }, [root, selector, dep, childSelector]);
  return { box, ready };
}
